import{z as B,x as A,o as i,c as d,q as r,j as l,D as E,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"时间片与公平调度","description":"","frontmatter":{"title":"时间片与公平调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timeslice-cfs.md","filePath":"cs/timeslice-cfs.md","lastUpdated":1791413859000}'),p={name:"cs/timeslice-cfs.md"};function m(c,a,u,C,D,h){const s=A("Mermaid");return i(),d("div",null,[a[2]||(a[2]=r('<h1 id="时间片与公平调度" tabindex="-1">时间片与公平调度 <a class="header-anchor" href="#时间片与公平调度" aria-label="Permalink to &quot;时间片与公平调度&quot;">​</a></h1><div class="epigraph"><p>完全公平调度试图让每条可运行任务分到与其权重成比例的 CPU 时间。</p><footer>—— 据 Linux CFS 设计直觉；Silberschatz et al. 对轮转与公平的整理</footer></div><p><a href="/cs/pi-pcp">上一课</a>把锁上的反转等待有界化；<a href="/cs/scheduling-metrics">调度指标</a>给出响应与公平等尺子。轮转用时间片改善响应，但仍把每条线程当同等的「下一个量子」。缺口是：交互与后台、不同 nice，需要<strong>按权重摊时间</strong>，而不是固定队列转圈。本课用时间片与 CFS 的虚拟运行时间当直觉，不当成内核源码课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯 FCFS 响应差；固定时间片轮转公平但无权重：后台编译与前台击键抢同一圈。缺口不是新的指标定义，而是一种分配：在任意窗口里，线程 \\(i\\) 获得的 CPU 份额接近 \\(w_i/\\sum w\\)。实现上，每次选「至今吃得最少（按权重折算）」的那条。</p><p>本课不把红黑树结点布局、<code>vruntime</code> 溢出细节写完，只钉这套直觉。</p><p><span class="marginnote">CFS 用虚拟运行时间：实际跑 \\(\\Delta t\\) 的线程，其 <code>vruntime</code> 增加约 \\(\\Delta t \\cdot w_0/w_i\\)。权重越大，虚拟时钟走得越慢，越容易被再次选中。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>时钟中断或主动让出时进入调度：比较可运行线程的虚拟运行时间，切到最小者；给它一段时间片（或直到它阻塞、直到别人的虚拟时间追上）。时间片不是魔法常数：太短切换开销压过吞吐，太长响应变差——尺子仍是<a href="/cs/scheduling-metrics">调度指标</a>那些。</p>',9)),(i(),l(o,null,{default:E(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20READY%5B%22%E5%B0%B1%E7%BB%AA%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%20VR%5B%22%E6%8C%89%E6%9D%83%E9%87%8D%E6%8A%98%E7%AE%97%E7%9A%84%E8%99%9A%E6%8B%9F%E6%97%B6%E9%97%B4%22%5D%0A%20%20VR%20--%3E%20PICK%5B%22%E9%80%89%E6%9C%80%E5%B0%8F%E8%80%85%E4%B8%8A%20CPU%22%5D%0A%20%20PICK%20--%3E%20TICK%5B%22%E8%B7%91%E4%B8%80%E6%AE%B5%E6%97%B6%E9%97%B4%E5%86%8D%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"阻塞的线程不累积「亏欠到无限」的简单模型即可：醒来时把虚拟时间接到当前最小附近，避免一下子垄断 CPU。Linux 的具体补偿是实现，主干只要求不饿死、不让睡很久的人醒来瞬间吞掉全部核心。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("公平是对"),e("strong",null,"可运行"),t("集合而言：在磁盘上睡的人不应靠「睡着也涨份额」抢走交互。时间片把"),e("a",{href:"/cs/scheduling-metrics"},"调度指标"),t("的响应指标变成可调旋钮；权重把「公平」从人数均等改成份额均等。上下文切换次数随可运行集合与片长变化，所以公平策略仍付切换税。")],-1)),a[6]||(a[6]=e("p",null,"权重怎么把「公平」从人数改成份额：",-1)),(i(),l(o,null,{default:E(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BB%BB%E5%8A%A1A%3A%20%E6%9D%83%E9%87%8D%202%22%5D%20--%3E%20CAL%5B%22vruntime%20%E5%A2%9E%E9%80%9F%20%3D%20%E5%AE%9E%E8%B7%91%E6%97%B6%E9%95%BF%20%C3%97%20w0%2F%E6%9D%83%E9%87%8D%22%5D%0A%20%20B%5B%22%E4%BB%BB%E5%8A%A1B%3A%20%E6%9D%83%E9%87%8D%200.5%22%5D%20--%3E%20CAL%0A%20%20CAL%20--%3E%20CMP%5B%22%E6%AF%8F%E6%AC%A1%E6%8C%91%20vruntime%20%E6%9C%80%E5%B0%8F%E8%80%85%22%5D%0A%20%20CMP%20--%3E%20RUN%5B%22%E4%B8%8A%20CPU%20%E8%B7%91%E4%B8%80%E6%AE%B5%22%5D%0A%20%20RUN%20--%3E%20UPD%5B%22%E5%90%84%E8%87%AA%E7%B4%AF%E5%8A%A0%E8%99%9A%E6%8B%9F%E6%97%B6%E9%97%B4%22%5D%0A%20%20UPD%20--%3E%20CMP%0A%20%20OUT%5B%22A%20%E8%99%9A%E6%8B%9F%E9%92%9F%E8%B5%B0%E5%BE%97%E6%85%A2%3A%20%E4%BB%BD%E9%A2%9D%E7%BA%A6%204%20%E5%80%8D%E4%BA%8E%20B%22%5D%20-.%E9%95%BF%E6%9C%9F%E7%BB%93%E6%9E%9C.-%3E%20CMP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：设基准权重 \\(w_0=1\\)，任务 A 权重 2、任务 B 权重 0.5。同样实跑 10 毫秒，A 的 vruntime 只涨 5，B 涨 20——A 的虚拟钟慢，更容易再次当选，长期下来 A 大约拿到 2/2.5 即八成时间，恰是 B 的 4 倍，等于权重之比。</span></p><p>本课不处理截止时间：公平摊时间可以让所有人错过期限。那是后课实时调度的对照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 Linux 内核实验指导，不保证与某主线版本的字段同名。不引入实时策略（<code>SCHED_FIFO</code>）与 deadline 调度。也不把多核共享缓存的调度写成 NUMA 课。</p><p><span class="marginnote">直觉类比：vruntime 像食堂里每人手里的「排队卡」——吃一口饭卡上数字就走一格，权重高的人卡走得慢，于是他排在前面更久。调度器永远让「卡上数字最小」的那位去打饭。</span></p><p>交互性启发式（睡眠补偿）是实现，不是公平份额的定义；本课以虚拟时间为准。</p><p>后课默认：通用分时按权重摊 CPU，用虚拟时间近似。有硬期限的任务不能靠这一套，后课对照。</p><p><span class="marginnote">常见误区：初学者容易以为公平就是「每人轮流跑同样长的片」——那只是人数公平。CFS 的公平是按权重摊份额；睡着的任务不涨 vruntime 也不欠账，醒来时被接到当前最小值附近，防止一口气吞掉整核。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时间片改善响应；权重把公平从「人次」改成「份额」。</li><li>CFS 直觉：跑得越少（折算后）越先上。</li><li>实时期限是另一套目标，不能从 vruntime 推出。</li><li>出处：Silberschatz et al., <em>OSC</em>；Linux CFS 设计讨论（Molnar 等），作直觉而非源码转写。</li></ul>',10))])}const F=B(p,[["render",m]]);export{_ as __pageData,F as default};
